    CSO.add(SOURCE_CATALOG: SOURCE_CATALOG, &fbb)
    CSO.add(SOURCE_URL: SOURCE_URL, &fbb)
    CSO.add(CITATION: CITATION, &fbb)
    return CSO.endCSO(&fbb, start: __start)
